/**
 * Compaction orchestrator — combines cut-point + summarization.
 * Returns the new message array and metadata for event emission.
 */
import type { Message, Model, UserMessage } from '@mariozechner/pi-ai'
import { Effect } from 'effect'

import { estimateMessageTokens, findCutPoint } from './cut-point'
import { generateSummary } from './summarize'

export interface CompactionResult {
  /** New message array (summary message + kept messages) */
  readonly newMessages: readonly Message[]
  /** The summary text generated by the LLM */
  readonly summaryText: string
  /** Number of messages that were summarized */
  readonly messagesSummarized: number
  /** Estimated tokens before compaction */
  readonly tokensBefore: number
  /** Estimated tokens after compaction */
  readonly tokensAfter: number
  /** Index where the cut was made */
  readonly cutIndex: number
}

/**
 * Execute compaction on a message array.
 *
 * 1. Find the optimal cut point
 * 2. Summarize old messages via LLM
 * 3. Return new message array: [summary as user message] + [kept messages]
 */
export function executeCompaction(
  messages: readonly Message[],
  model: Model<any>,
  keepRecentTokens: number,
): Effect.Effect<CompactionResult, Error> {
  return Effect.gen(function* () {
    const cutResult = findCutPoint(messages, keepRecentTokens)
    if (!cutResult) {
      return yield* Effect.fail(
        new Error('Nothing to compact — conversation too short or within token budget'),
      )
    }

    let tokensBefore = 0
    for (const message of messages) {
      tokensBefore += estimateMessageTokens(message)
    }

    const summaryText = yield* generateSummary(cutResult.messagesToSummarize, model)

    const summaryMessage: UserMessage = {
      role: 'user',
      content: `[Previous conversation summary — ${cutResult.messagesToSummarize.length} messages compacted]\n\n${summaryText}`,
      timestamp: Date.now(),
    }

    const newMessages: readonly Message[] = [summaryMessage, ...cutResult.messagesToKeep]

    let tokensAfter = 0
    for (const message of newMessages) {
      tokensAfter += estimateMessageTokens(message)
    }

    return {
      newMessages,
      summaryText,
      messagesSummarized: cutResult.messagesToSummarize.length,
      tokensBefore,
      tokensAfter,
      cutIndex: cutResult.cutIndex,
    }
  }).pipe(Effect.withSpan('tmnl.harness.compaction.execute'))
}
